7-  workspace_id text not null references public.workspaces(id) on delete cascade,
8-  name text not null check (char_length(btrim(name)) between 1 and 60),
9-  kid text not null unique check (kid ~ '^[0-9a-f]{24}$'),
10-  hash text not null check (hash ~ '^[0-9a-f]{64}$'),
11-  scope text not null check (scope in ('read','write')),
